from itertools import combinations


def most_competitive(nums, k):
    best = None
    n = len(nums)
    for combo_indices in combinations(range(n), k):
        candidate = [nums[i] for i in combo_indices]
        if best is None or candidate < best:
            best = candidate
    return best


if __name__ == "__main__":
    print(most_competitive([3, 5, 2, 6], 2))
    print(most_competitive([2, 4, 3, 3, 5, 4, 9, 6], 4))

