import java.util.*;

public class Main {
    static int[] mostCompetitive(int[] nums, int k) {
        List<Integer> combo = new ArrayList<>();
        return combine(nums, 0, k, combo, null);
    }

    static int[] combine(int[] nums, int start, int k, List<Integer> combo, int[] best) {
        int n = nums.length;
        if (combo.size() == k) {
            int[] candidate = new int[k];
            for (int i = 0; i < k; i++) candidate[i] = combo.get(i);
            if (best == null || isSmaller(candidate, best)) return candidate;
            return best;
        }
        for (int i = start; i <= n - (k - combo.size()); i++) {
            combo.add(nums[i]);
            best = combine(nums, i + 1, k, combo, best);
            combo.remove(combo.size() - 1);
        }
        return best;
    }

    static boolean isSmaller(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) {
            if (a[i] != b[i]) return a[i] < b[i];
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(mostCompetitive(new int[]{3, 5, 2, 6}, 2)));
        System.out.println(Arrays.toString(mostCompetitive(new int[]{2, 4, 3, 3, 5, 4, 9, 6}, 4)));
    }
}

