#include <bits/stdc++.h>
using namespace std;

bool isSmaller(vector<int>& a, vector<int>& b) {
    for (int i = 0; i < (int)a.size(); i++) {
        if (a[i] != b[i]) return a[i] < b[i];
    }
    return false;
}

void combine(vector<int>& nums, int start, int k, vector<int>& combo, vector<int>& best) {
    int n = nums.size();
    if ((int)combo.size() == k) {
        if (best.empty() || isSmaller(combo, best)) best = combo;
        return;
    }
    for (int i = start; i <= n - (k - (int)combo.size()); i++) {
        combo.push_back(nums[i]);
        combine(nums, i + 1, k, combo, best);
        combo.pop_back();
    }
}

vector<int> mostCompetitive(vector<int>& nums, int k) {
    vector<int> combo, best;
    combine(nums, 0, k, combo, best);
    return best;
}

