#include <bits/stdc++.h>
using namespace std;

vector<int> mostCompetitive(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> stack;

    for (int i = 0; i < n; i++) {
        while (!stack.empty() && stack.back() > nums[i] && ((int)stack.size() - 1 + n - i) >= k) {
            stack.pop_back();
        }
        if ((int)stack.size() < k) {
            stack.push_back(nums[i]);
        }
    }
    return stack;
}

int main() {
    vector<int> nums1 = {3, 5, 2, 6};
